import re, difflib

known = 'It was on a dreary night of November, that I beheld the accomplishment of my toils.'
read = input('Text that OCR returned (try the known text with one letter changed, e.g. IT was on ... ): ')

def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

def norm(t):
    return re.sub(r'\s+', ' ', t).strip()

ref, hyp = norm(known), norm(read)
d = edit_distance(ref, hyp)
print('characters in the known text:', len(ref))
print('edit distance:', d, '| character error rate:', round(d / len(ref), 4))
wd = edit_distance(ref.split(), hyp.split())
print('word error rate:', round(wd / len(ref.split()), 4))
for op, a1, a2, b1, b2 in difflib.SequenceMatcher(None, ref.split(), hyp.split()).get_opcodes():
    if op != 'equal':
        print(op, ref.split()[a1:a2], '->', hyp.split()[b1:b2])
